func (r *GitHubRepositoryReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
    log := ctrl.LoggerFrom(ctx).WithValues("githubrepository", req.NamespacedName)

    var repo repov1.GitHubRepository
    if err := r.Get(ctx, req.NamespacedName, &repo); err != nil {
        if apierrors.IsNotFound(err) {
            return ctrl.Result{}, nil
        }
        return ctrl.Result{}, err
    }

    // Defer status update.
    defer func() {
        if err := r.Status().Update(ctx, &repo); err != nil {
            log.Error(err, "failed to update status")
        }
    }()

    repo.Status.Phase = "Reconciling"
    meta.SetStatusCondition(&repo.Status.Conditions, metav1.Condition{
        Type:    "Ready",
        Status:  metav1.ConditionFalse,
        Reason:  "Reconciling",
        Message: "Reconciliation in progress",
    })

    // TODO: interact with GitHub API.

    repo.Status.Phase = "Ready"
    repo.Status.ObservedGeneration = repo.Generation
    meta.SetStatusCondition(&repo.Status.Conditions, metav1.Condition{
        Type:    "Ready",
        Status:  metav1.ConditionTrue,
        Reason:  "Success",
        Message: "Repository reconciled",
    })

    return ctrl.Result{}, nil
}

package main

import (
    "flag"
    "os"

    "k8s.io/apimachinery/pkg/runtime"
    utilruntime "k8s.io/apimachinery/pkg/util/runtime"
    clientgoscheme "k8s.io/client-go/kubernetes/scheme"
    ctrl "sigs.k8s.io/controller-runtime"
    "sigs.k8s.io/controller-runtime/pkg/healthz"
    "sigs.k8s.io/controller-runtime/pkg/log/zap"

    repov1 "github.com/example/github-repo-controller/api/v1"
    "github.com/example/github-repo-controller/internal/controller"
)

var (
    scheme   = runtime.NewScheme()
    setupLog = ctrl.Log.WithName("setup")
)

func init() {
    utilruntime.Must(clientgoscheme.AddToScheme(scheme))
    utilruntime.Must(repov1.AddToScheme(scheme))
}

func main() {
    var metricsAddr string
    var probeAddr string
    flag.StringVar(&metricsAddr, "metrics-bind-address", ":8080", "The address the metric endpoint binds to.")
    flag.StringVar(&probeAddr, "health-probe-bind-address", ":8081", "The address the probe endpoint binds to.")
    opts := zap.Options{Development: true}
    opts.BindFlags(flag.CommandLine)
    flag.Parse()

    ctrl.SetLogger(zap.New(zap.UseFlagOptions(&opts)))

    mgr, err := ctrl.NewManager(ctrl.GetConfigOrDie(), ctrl.Options{
        Scheme:                 scheme,
        MetricsBindAddress:     metricsAddr,
        HealthProbeBindAddress: probeAddr,
    })
    if err != nil {
        setupLog.Error(err, "unable to start manager")
        os.Exit(1)
    }

    if err = (&controller.GitHubRepositoryReconciler{
        Client: mgr.GetClient(),
        Scheme: mgr.GetScheme(),
    }).SetupWithManager(mgr); err != nil {
        setupLog.Error(err, "unable to create controller", "controller", "GitHubRepository")
        os.Exit(1)
    }

    if err := mgr.AddHealthzCheck("healthz", healthz.Ping); err != nil {
        setupLog.Error(err, "unable to set up health check")
        os.Exit(1)
    }
    if err := mgr.AddReadyzCheck("readyz", healthz.Ping); err != nil {
        setupLog.Error(err, "unable to set up ready check")
        os.Exit(1)
    }

    setupLog.Info("starting manager")
    if err := mgr.Start(ctrl.SetupSignalHandler()); err != nil {
        setupLog.Error(err, "problem running manager")
        os.Exit(1)
    }
}

func TestGitHubRepositoryReconcile(t *testing.T) {
    g := NewWithT(t)

    repo := &repov1.GitHubRepository{
        ObjectMeta: metav1.ObjectMeta{
            Name:      "test-repo",
            Namespace: "default",
        },
        Spec: repov1.GitHubRepositorySpec{
            Owner:      "example",
            Name:       "test",
            Visibility: "public",
        },
    }

    client := fake.NewClientBuilder().WithScheme(scheme).WithObjects(repo).Build()
    r := &GitHubRepositoryReconciler{Client: client, Scheme: scheme}

    _, err := r.Reconcile(context.Background(), reconcile.Request{
        NamespacedName: types.NamespacedName{Name: repo.Name, Namespace: repo.Namespace},
    })
    g.Expect(err).NotTo(HaveOccurred())

    g.Expect(client.Get(context.Background(), types.NamespacedName{Name: repo.Name, Namespace: repo.Namespace}, repo)).To(Succeed())
    g.Expect(repo.Status.Phase).To(Equal("Ready"))
}

// PlatformClient abstracts GitHub API interactions.
type PlatformClient interface {
    CreateOrUpdateRepository(ctx context.Context, owner, name string, repo *RepositoryConfig) (*RepositoryInfo, error)
    DeleteRepository(ctx context.Context, owner, name string) error
}

// RepositoryConfig carries desired repository settings.
type RepositoryConfig struct {
    Description      string
    Visibility       string
    InitializeReadme bool
    LicenseTemplate  string
}

// RepositoryInfo carries observed repository settings.
type RepositoryInfo struct {
    URL        string
    Visibility string
}

// In tests, provide a fake implementation:
// type fakeClient struct { ... }
// and inject it into the reconciler as r.PlatformClient.

const githubRepoFinalizer = "repo.example.com/finalizer"

func (r *GitHubRepositoryReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
    var repo repov1.GitHubRepository
    if err := r.Get(ctx, req.NamespacedName, &repo); err != nil {
        return ctrl.Result{}, client.IgnoreNotFound(err)
    }

    if repo.DeletionTimestamp.IsZero() {
        if !controllerutil.ContainsFinalizer(&repo, githubRepoFinalizer) {
            controllerutil.AddFinalizer(&repo, githubRepoFinalizer)
            return ctrl.Result{}, r.Update(ctx, &repo)
        }
    } else {
        if controllerutil.ContainsFinalizer(&repo, githubRepoFinalizer) {
            if err := r.PlatformClient.DeleteRepository(ctx, repo.Spec.Owner, repo.Spec.Name); err != nil {
                return ctrl.Result{}, err
            }
            controllerutil.RemoveFinalizer(&repo, githubRepoFinalizer)
            return ctrl.Result{}, r.Update(ctx, &repo)
        }
        return ctrl.Result{}, nil
    }

    // ... normal reconcile
    return ctrl.Result{}, nil
}
